from pathlib import Path
import re, textwrap, html

base = Path('/mnt/data/site_v5')

def paras(text):
    out=[]
    for line in textwrap.dedent(text).strip().split('\n'):
        line=line.strip()
        if not line:
            continue
        if line.startswith('- '):
            out.append(f'<li>{html.escape(line[2:])}</li>')
        elif re.match(r'^\d+\.\s+', line):
            out.append(f'<li>{html.escape(re.sub(r"^\\d+\\.\\s+", "", line))}</li>')
        elif line.startswith('### '):
            out.append(f'<h3>{html.escape(line[4:])}</h3>')
        elif line.startswith('## '):
            out.append(f'<h2>{html.escape(line[3:])}</h2>')
        else:
            out.append(f'<p>{html.escape(line)}</p>')
    # wrap consecutive li into ul? simpler, produce li directly okay inside div but invalid. We'll make via markdown sections manually elsewhere.
    return '\n'.join(out)

def details(title, body, open=False):
    return f'<details {"open" if open else ""}><summary>{html.escape(title)}</summary>\n{body}\n</details>'

def p(text):
    return f'<p>{html.escape(text)}</p>'

def ul(items):
    return '<ul>\n' + '\n'.join(f'<li>{html.escape(i)}</li>' for i in items) + '\n</ul>'

def ol(items):
    return '<ol>\n' + '\n'.join(f'<li>{html.escape(i)}</li>' for i in items) + '\n</ol>'

