stroevoy = ''
stroevoy += p('Строевой устав — официальный документ, содержащий положения и правила, определяющие строевые приёмы, порядок движения и действия в различных условиях. На его основе организуется и проводится строевая подготовка.')
stroevoy += '<h3>Виды построений</h3>' + ul(['Небоевые построения: шеренга, колонна.', 'Боевые построения: клин, боевая стена.', 'Сопровождающие построения: VIP, заложник.'])
stroevoy += '<h3>Небоевые построения</h3>' + p('Шеренга — строй, в котором бойцы стоят плечом к плечу. Началом строя является боец, стоящий правее всех; остальные строятся слева от него.') + p('Колонна — строй, при котором бойцы стоят друг за другом. При двойной колонне бойцы становятся поочерёдно в левое и правое плечо руководящего строем; если бойцов нечётное количество, последний становится зеркально руководящему в конце строя между двумя колоннами.')
stroevoy += '<h3>Боевые построения</h3>' + p('Клин — наступательное построение боевого порядка, предназначенное для сближения с противником и прорыва вражеского строя. По команде руководящего строем бойцы строятся за ним, организуя диагонали слева и справа, предварительно взяв оружие и сняв его с предохранителя.') + p('Боевая стена — построение для увеличения огневой мощи отряда, удержания позиций и отражения атак по фронту. Одинарная стена используется на открытой местности; двойная — в замкнутых помещениях, передняя шеренга сидит, задняя стоит.')
stroevoy += '<h3>Сопровождающие построения</h3>' + p('VIP — построение для защиты и сопровождения особо важного объекта. Бойцы встают со своих азимутов на расстоянии одного клона от цели, смотрят в противоположную сторону от VIP, держат оружие на предохранителе. При сокращении дистанции неизвестным лицом боец делает предупредительный выстрел перед ногами и требует уйти, при игнорировании — оглушает.') + p('Заложник — построение для захвата, удержания и передислокации цели. Бойцы захвата направляют оружие в нижнюю часть заложника, плотно окружают его, не выполняют приказы или просьбы цели; при неподчинении цель оглушается, окружается, лишается оружия, связи и снаряжения.')
stroevoy += '<h3>Правила поведения в строю</h3>' + ol(['Запрещается входить в строй или уходить из строя до окончания тренировки или мероприятия без разрешения командира строя.', 'Все участники строя должны быть одеты в форму и сохранять её чистоту и аккуратность.', 'При проходе в строю необходимо сохранять прямую спину и равномерную походку.', 'Запрещается разговаривать, курить или выполнять действия, отвлекающие от строевого порядка.', 'Участники строя должны следовать командам командира и выполнять их точно и незамедлительно.', 'Запрещается покидать строй без разрешения.', 'Во время строя необходимо сохранять тишину.', 'Запрещается проявление агрессивного поведения или неуважения.', 'Участники строя должны быть внимательны и знать правила безопасности при движениях и упражнениях.'])
stroevoy += '<h3>Строевые команды</h3>' + ul(['Вспышка с тыла — падение на землю туловищем вперёд.', 'Вспышка с фронта — падение на землю туловищем назад.', 'Вспышка справа — падение туловищем влево.', 'Вспышка слева — падение туловищем вправо.', 'Смирно — встать, держа голову прямо и руки по швам.', 'Равняйсь — стоя смирно, повернуть голову направо.', 'Вольно — окончить стойку смирно, не сходя с места.', 'Выполнять — немедленно начать выполнение задачи.', 'Кругом — поворот на 180° через левое плечо.', 'Напра-во — поворот на 90° вправо.', 'Нале-во — поворот на 90° влево.', 'Отставить — закончить выполнение последней поставленной задачи.'])

shtab = ''
shtab += p('Штаб — структура управления вооружёнными силами, отвечающая за координацию подразделений, стратегию войны, назначение боевых миссий, утверждение планов и управление должностными лицами.')
shtab += '<h3>Структурная иерархия командования вооружённых сил</h3>' + ul(['Военный Совет Генерального Штаба — высший орган управления вооружёнными силами.', 'Генеральный Штаб — структура управления армией, занимающаяся руководством подразделениями, кооперацией и стратегией войны.', 'Секторальный Штаб — представительство Генерального Штаба в секторе; координирует и управляет подразделениями секторальной армии.', 'Вооружённые силы Республики состоят из ВАР, флота, корпуса звёздных истребителей и военной разведки.'])
shtab += '<h3>Командующий Секторальной Армией</h3>' + p('Уполномоченное лицо, в задачи которого входит ведение стратегии войны на территории одной секторальной армии.') + '<h4>Полномочия</h4>' + ul(['Управление всеми военными ресурсами сектора.', 'Руководство всеми формированиями и должностными лицами сектора.']) + '<h4>Обязанности</h4>' + ul(['Защита интересов Республики.', 'Ведение наиболее успешной стратегии войны и кураторство военных кампаний.', 'Введение Генерального Штаба ВАР в курс принимаемых решений и действий.'])
shtab += '<h3>Начальник штаба</h3>' + p('Правая рука командующего секторальной армии. Организует деятельность штабных офицеров, издаёт локальные распорядительные акты и приказы, определяет стратегию боевых действий на территории сектора и отвечает за военные объекты сектора.') + '<h4>Права</h4>' + ul(['Назначение и отстранение нижестоящих офицеров секторального штаба.', 'Координация боевых операций и утверждение плана боевых действий сектора.', 'Распоряжение военными ресурсами сектора.', 'Командование всеми формированиями и боевыми единицами сектора.', 'Вынесение санкций бойцам ВАР.']) + '<h4>Обязанности</h4>' + ul(['Содействовать командующему секторальной армии в достижении стратегических задач.', 'Организовывать работу штаба и повышать эффективность штабных офицеров.', 'Обеспечивать штатное функционирование всех военных объектов сектора.'])
shtab += '<h3>Заместители начальника штаба</h3>' + p('Офицеры старшего звена выполняют задачи в своей сфере, содействуют начальнику штаба и могут принимать командование при необходимости.') + ul(['Комендант штаба — обеспечивает функционирование и безопасность военных объектов сектора, внутренний распорядок, воинскую дисциплину и контроль охранных формирований.', 'Начальник оперативного отдела — планирует операции, налаживает координацию подразделений, контролирует боевую подготовку и выполнение боевых задач.', 'Начальник медицинской службы — организует медицинские подразделения, оказание помощи, снабжение медицинских станций и контроль медицинского корпуса.', 'Ответственный за логистику и снабжение — организует снабжение зон боевых действий и ВО оборудованием, боеприпасами и техникой, контролирует техническое состояние объектов и ремонтные работы.'])
shtab += '<h3>Младшие офицеры штаба</h3>' + p('Младшие офицеры штаба являются посредниками заместителей начальника штаба на военных объектах, отвечают за конкретную сферу деятельности и предоставляют отчёты в секторальный штаб.') + '<h4>Права</h4>' + ul(['Командовать боевыми единицами при отсутствии командира их формирования или по согласованию.', 'Распоряжаться ресурсами военного объекта для выполнения своих обязанностей.', 'Менять коды на базе.', 'Требовать содействия от других офицеров штаба.', 'Принимать обращения от боевых единиц и принимать решения на их основании.']) + '<h4>Обязанности</h4>' + ul(['Выполнять обязанности заместителей начальника штаба своей сферы в рамках закреплённого военного объекта.', 'Документировать и вести отчётность действий и решений.', 'Непредвзято относиться к бойцам, офицерам и формированиям.'])

sb = ''
sb += p('Служба безопасности (СБ) — особое подразделение ВАР, обеспечивающее безопасность на военных объектах Республики и выполняющее функцию военной полиции. Подразделения корусантской гвардии также считаются СБ.')
sb += p('Сотрудники СБ подотчётны штабу секторальной армии, в частности офицерам комендатуры, и несут ответственность за закреплённые военные объекты. Объектом интереса СБ являются девиантное поведение, нарушение устава, материальный вред ВАР, нарушение функционирования ВО и диверсии.')
sb += '<h3>Регламент</h3>' + '<h4>Обязанности служащих СБ</h4>' + ol(['Поддерживать порядок и безопасность на территории военного объекта и прилегающих объектов.', 'Пресекать нарушения любыми боевыми единицами ВАР.', 'Исполнять указания представителей штаба и вышестоящих лиц.', 'Единоразово предъявлять IDN по требованию.', 'Предъявлять приказ в случае его исполнения, если приказ опубликован письменно.', 'Самоидентифицироваться при взаимодействии с юнитами без системы ВИД.', 'Строго следовать внутреннему регламенту.'])
sb += '<h4>Полномочия СБ</h4>' + ol(['Открыто носить оружие на предохранителе во время зелёного кода.', 'Производить задержание и арест юнитов, нарушивших или подозреваемых в нарушении устава ВАР и правовых документов.', 'Беспрепятственно проходить на охраняемые территории с ограниченным пропускным режимом при исполнении, кроме специальных исключений.', 'Выходить за пределы ВО при исполнении.', 'Проводить следственные мероприятия, разбирательства и охранную деятельность.', 'Использовать специальные средства и технику.', 'Закрывать территории ВО и устанавливать временный пропускной режим.', 'Задерживать лиц, мешающих деятельности СБ.', 'Останавливать транспортные средства, проверять документы пилотов и маршруты, изымать документы.', 'Менять код на базе для обеспечения безопасности.', 'Проверять документы юнитов, не распознаваемых системой ВИД.'])
sb += '<h3>Компетенции</h3>' + ul(['Бойцы СБ должны быть точны и сдержанны в общении, не провоцировать и не оскорблять бойцов.', 'Запрещена нецензурная и вульгарная лексика.', 'Требуется соблюдать уважение и осторожность при построении диалога.', 'Допускается отсутствие снисходительности к задержанным, подозреваемым и бойцам, не уважающим СБ.', 'Сотрудник СБ обязан определять девиантное поведение и сообщать о таких инцидентах старшему сотруднику.'])
sb += '<h3>Степени нарушения</h3>' + ul(['Лёгкие нарушения — непредумышленные преступления без нарушения структуры ВО и вреда здоровью. Повтор после предупреждения считается предумышленным.', 'Средние нарушения — предумышленные преступления, не критически нарушающие работу ВО, либо действия с непредумышленным вредом здоровью.', 'Тяжёлые нарушения — преступления с критическим нарушением структуры и работы ВО или намеренным вредом здоровью.'])
sb += '<h3>Регламент задержания</h3>' + ol(['Попытаться выйти на контакт с нарушителем, потребовать прекращения противоправных действий и объяснить нарушение. При неповиновении переходить к остановке.', 'Остановить нарушителя. Разрешено использовать оружие в оглушающем режиме, а при тяжком преступлении с угрозой жизни — боевой режим для лишения дееспособности.', 'После поимки изъять вооружение, снаряжение и средства связи.', 'Конвоировать нарушителя в КПЗ или допросную при необходимости следствия.', 'С момента доставки в КПЗ боец считается задержанным и лишается должностных полномочий до снятия обвинений.', 'После доставки сотрудники СБ обязаны объяснить причину задержания, выслушать аргументы и принять решение о наказании или снятии обвинений.', 'До вынесения наказания задержание длится не более часа; время следственных мероприятий не учитывается.', 'Младшие сотрудники СБ могут удерживать подозреваемого до прибытия старшего, но не более 24 часов при наличии состава преступления и доказательств.'])
sb += '<h3>Меры пресечения</h3>' + ul(['Категория I — устное предупреждение или физические упражнения, выдаётся за лёгкие нарушения.', 'Категория II — срок в КПЗ до 24 часов или до распоряжения командования, с занесением в личное дело.', 'Категория III — срок в КПЗ до 7 дней с инициацией расследования до решения командования или суда.', 'Категория IV — срок в КПЗ с расследованием до назначения судебного заседания.', 'Наказания III и IV категорий могут выдаваться исключительно по распоряжению 1LT+. IV категория предполагает обязательный трибунал.'])
sb += '<h3>Процедура расследования</h3>' + p('Расследование инициируется по распоряжению 1LT+ при наказаниях III и IV категорий. Наблюдатель выбирает ответственного следователя из числа сотрудников СБ, не относящихся к делу. Ответственный документирует процесс, сохраняет доказательства, не скрывает обстоятельства и имеет приоритет при назначении стороны обвинения для суда.')
sb += '<h3>Отчётность</h3>' + p('Сотрудники СБ обязаны вести официальную отчётность. Рапорты обязательны для действий СБ, кроме патрульной и постовой службы, обыска или проверки прибывших лиц и транспорта, наказаний категории I, выявления девиантного поведения и задержаний впоследствии оправданных бойцов. Рапорты составляются в течение 24 часов, дополнения к расследованию — не позднее трёх часов.')
